-- F0 schema, part 1: configuration, identities, secrets (SHAA-193).
-- Source: data contract v0.7.10 sections 3.3a, 3.2.6, 3.7, 4, 8.1a/8.1b; ADR-0001 rev 15 section 7.2.
-- Runs as poolrouter_owner. IDs are generated by the application (UUIDv7), so no DB defaults.

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------- admin users (ADR-0003 rev 4 section 3.6 / 8, Addendum A)
CREATE TABLE client (
  client_id uuid PRIMARY KEY,
  nama text NOT NULL UNIQUE CHECK (length(nama) BETWEEN 1 AND 200),
  aktif boolean NOT NULL DEFAULT true,
  -- contract L-04
  limiter_penolakan_burst integer NOT NULL DEFAULT 20 CHECK (limiter_penolakan_burst BETWEEN 1 AND 1000),
  limiter_penolakan_isi_ulang_per_detik numeric(6,2) NOT NULL DEFAULT 1.00
    CHECK (limiter_penolakan_isi_ulang_per_detik BETWEEN 0.10 AND 100.00),
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  diubah_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE admin_user (
  pengguna_id uuid PRIMARY KEY,
  username text NOT NULL CHECK (username = lower(username) AND length(username) BETWEEN 3 AND 100),
  password_hash text NOT NULL,                        -- argon2id PHC string
  aktif boolean NOT NULL DEFAULT true,
  client_id uuid REFERENCES client (client_id),       -- set for client owners only
  -- ADR-0003 Addendum A section 7.2: NULL = not set yet, no default
  bahasa_ui text NULL CHECK (bahasa_ui IN ('id', 'en')),
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  diubah_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX admin_user_username_uq ON admin_user (username);

-- Role assignment with separation of duties (contract A-02, ADR-0001 section 7.2).
CREATE TABLE admin_user_peran (
  pengguna_id uuid NOT NULL REFERENCES admin_user (pengguna_id),
  peran text NOT NULL CHECK (peran IN ('auditor', 'operator', 'platform_admin', 'client_owner')),
  diajukan_oleh uuid NOT NULL REFERENCES admin_user (pengguna_id),
  disetujui_oleh uuid REFERENCES admin_user (pengguna_id),
  berlaku_sampai timestamptz,                         -- ADR-0003 PoC control: auditor role must expire
  diberikan_at timestamptz NOT NULL DEFAULT now(),
  dicabut_at timestamptz,
  PRIMARY KEY (pengguna_id, peran),
  -- A-02: nobody grants auditor/operator to themselves, and the approver differs from both.
  CONSTRAINT peran_pemisahan_tugas CHECK (
    peran NOT IN ('auditor', 'operator')
    OR (disetujui_oleh IS NOT NULL
        AND diajukan_oleh <> pengguna_id
        AND disetujui_oleh <> pengguna_id
        AND disetujui_oleh <> diajukan_oleh)
  )
);

CREATE TABLE admin_session (
  sesi_id uuid PRIMARY KEY,
  token_sha256 bytea NOT NULL UNIQUE CHECK (octet_length(token_sha256) = 32),
  pengguna_id uuid NOT NULL REFERENCES admin_user (pengguna_id),
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  terakhir_aktif_at timestamptz NOT NULL DEFAULT now(),
  kedaluwarsa_at timestamptz NOT NULL,                -- absolute limit (8 h)
  user_agent text CHECK (length(user_agent) <= 512)
);
CREATE INDEX admin_session_pengguna_idx ON admin_session (pengguna_id);

CREATE FUNCTION tg_client_owner_has_client() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.peran = 'client_owner'
     AND (SELECT client_id FROM admin_user WHERE pengguna_id = NEW.pengguna_id) IS NULL THEN
    RAISE EXCEPTION 'client_owner requires admin_user.client_id' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER admin_user_peran_client_owner BEFORE INSERT OR UPDATE ON admin_user_peran
  FOR EACH ROW EXECUTE FUNCTION tg_client_owner_has_client();

-- ---------------------------------------------------------------- provider
CREATE TABLE provider (
  provider_id uuid PRIMARY KEY,
  nama text NOT NULL UNIQUE CHECK (length(nama) BETWEEN 1 AND 200),
  aktif boolean NOT NULL DEFAULT true,
  wajib_log_nik boolean NOT NULL DEFAULT true,
  data_balikan_aktif boolean NOT NULL DEFAULT false,  -- H-01: Dukcapil = true
  config_versi_aktif integer,                         -- points at provider_config_versi.versi
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  diubah_at timestamptz NOT NULL DEFAULT now()
);

-- Immutable version history (contract V-01..V-05).
CREATE TABLE provider_config_versi (
  provider_id uuid NOT NULL REFERENCES provider (provider_id),
  versi integer NOT NULL CHECK (versi >= 1),
  config_schema_version integer NOT NULL CHECK (config_schema_version = 1),   -- V-05: only 1 in F0
  log_mode text NOT NULL CHECK (log_mode IN ('metadata_only', 'full_payload')),
  dokumen jsonb NOT NULL,                             -- template, validation, response schema, tls_trust, base URL, output params
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  dibuat_oleh uuid NOT NULL REFERENCES admin_user (pengguna_id),
  PRIMARY KEY (provider_id, versi)
);

-- Provider secrets: a different table from client_webhook (contract W-01). Write-only for pr_admin_api.
CREATE TABLE provider_secret (
  provider_id uuid NOT NULL REFERENCES provider (provider_id),
  nama_secret text NOT NULL CHECK (nama_secret ~ '^[A-Za-z][A-Za-z0-9_]{0,63}$'),
  secret_versi integer NOT NULL DEFAULT 1 CHECK (secret_versi >= 1),
  secret_ciphertext bytea NOT NULL,
  secret_dek_terbungkus bytea NOT NULL,
  secret_nonce bytea NOT NULL,
  kek_id varchar(100) NOT NULL,
  diubah_at timestamptz NOT NULL DEFAULT now(),
  diubah_oleh uuid NOT NULL REFERENCES admin_user (pengguna_id),
  PRIMARY KEY (provider_id, nama_secret)
);

-- ---------------------------------------------------------------- upstream pool (contract 3.3a KP-01..KP-07)
CREATE TABLE upstream_pool (
  upstream_pool_id uuid PRIMARY KEY,
  provider_id uuid NOT NULL REFERENCES provider (provider_id),
  nama text NOT NULL UNIQUE CHECK (length(nama) BETWEEN 1 AND 200),
  aktif boolean NOT NULL DEFAULT true,
  kuota_harian integer NOT NULL CHECK (kuota_harian > 0),
  porsi_sync_maks numeric(4,3) NOT NULL DEFAULT 0.200 CHECK (porsi_sync_maks BETWEEN 0 AND 1),   -- K-10
  parameter_dispatch jsonb NOT NULL DEFAULT '{}'::jsonb,   -- rate K-22, concurrency, random delay K-05 (not defined in contract section 3)
  -- KP-01
  margin_kuota numeric(4,3) NOT NULL DEFAULT 0.010 CHECK (margin_kuota BETWEEN 0.001 AND 0.200),
  batas_percobaan integer NOT NULL DEFAULT 3 CHECK (batas_percobaan BETWEEN 1 AND 5),
  retry_backoff_base_detik integer NOT NULL DEFAULT 5 CHECK (retry_backoff_base_detik BETWEEN 1 AND 300),
  retry_backoff_cap_detik integer NOT NULL DEFAULT 300 CHECK (retry_backoff_cap_detik <= 3600),
  retry_rasio numeric(4,3) NOT NULL DEFAULT 0.100 CHECK (retry_rasio BETWEEN 0 AND 0.500),
  retry_min_per_jam integer NOT NULL DEFAULT 20 CHECK (retry_min_per_jam BETWEEN 0 AND 10000),
  jendela_kuota text NOT NULL DEFAULT 'bergulir_24j' CHECK (jendela_kuota IN ('bergulir_24j', 'kalender')),
  reset_kuota_jam time(0) NOT NULL DEFAULT '00:00' CHECK (date_part('second', reset_kuota_jam) = 0),
  reset_kuota_zona varchar(64) NOT NULL DEFAULT 'Asia/Jakarta',
  -- KP-02: a reset change takes effect at berlaku_mulai = end of the running period
  reset_kuota_jam_berikut time(0) CHECK (date_part('second', reset_kuota_jam_berikut) = 0),
  reset_kuota_zona_berikut varchar(64),
  reset_kuota_berlaku_mulai timestamptz,
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  diubah_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT backoff_cap_ge_base CHECK (retry_backoff_cap_detik >= retry_backoff_base_detik),
  CONSTRAINT reset_berikut_lengkap CHECK (
    (reset_kuota_jam_berikut IS NULL) = (reset_kuota_zona_berikut IS NULL)
    AND (reset_kuota_jam_berikut IS NULL) = (reset_kuota_berlaku_mulai IS NULL)
  )
);

CREATE FUNCTION tg_validasi_zona() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  -- IANA names only; fixed offsets such as '+07:00' are rejected (KP-01).
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.reset_kuota_zona)
     OR NEW.reset_kuota_zona ~ '^[+-]' THEN
    RAISE EXCEPTION 'reset_kuota_zona harus nama zona IANA: %', NEW.reset_kuota_zona USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reset_kuota_zona_berikut IS NOT NULL
     AND (NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.reset_kuota_zona_berikut)
          OR NEW.reset_kuota_zona_berikut ~ '^[+-]') THEN
    RAISE EXCEPTION 'reset_kuota_zona_berikut harus nama zona IANA' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER upstream_pool_zona BEFORE INSERT OR UPDATE ON upstream_pool
  FOR EACH ROW EXECUTE FUNCTION tg_validasi_zona();

-- ---------------------------------------------------------------- downstream pool, endpoint
CREATE TABLE downstream_pool (
  downstream_pool_id uuid PRIMARY KEY,
  nama text NOT NULL UNIQUE CHECK (length(nama) BETWEEN 1 AND 200),
  aktif boolean NOT NULL DEFAULT true,
  prioritas integer NOT NULL CHECK (prioritas >= 1),
  ttl_antrean_detik integer NOT NULL DEFAULT 86400 CHECK (ttl_antrean_detik > 0),   -- K-18
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  diubah_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE downstream_pool_rute (
  downstream_pool_id uuid NOT NULL REFERENCES downstream_pool (downstream_pool_id),
  upstream_pool_id uuid NOT NULL REFERENCES upstream_pool (upstream_pool_id),
  PRIMARY KEY (downstream_pool_id, upstream_pool_id)
);

CREATE TABLE downstream_endpoint (
  downstream_endpoint_id uuid PRIMARY KEY,
  nama text NOT NULL UNIQUE CHECK (length(nama) BETWEEN 1 AND 200),
  provider_id uuid NOT NULL REFERENCES provider (provider_id),
  downstream_pool_id uuid NOT NULL REFERENCES downstream_pool (downstream_pool_id),   -- default / automatic pool
  aktif boolean NOT NULL DEFAULT true,
  config_versi_aktif integer,
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  diubah_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE endpoint_config_versi (
  downstream_endpoint_id uuid NOT NULL REFERENCES downstream_endpoint (downstream_endpoint_id),
  versi integer NOT NULL CHECK (versi >= 1),
  config_schema_version integer NOT NULL CHECK (config_schema_version = 1),
  log_mode text CHECK (log_mode IN ('metadata_only', 'full_payload')),   -- NULL = inherit; may only tighten (admin API, 422)
  dokumen jsonb NOT NULL,                              -- parameter_literal (TRESHOLD) etc.
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  dibuat_oleh uuid NOT NULL REFERENCES admin_user (pengguna_id),
  PRIMARY KEY (downstream_endpoint_id, versi)
);

-- Contract section 4.
CREATE TABLE endpoint_metadata_field (
  downstream_endpoint_id uuid NOT NULL REFERENCES downstream_endpoint (downstream_endpoint_id),
  nama_field varchar(64) NOT NULL CHECK (nama_field ~ '^[a-z][a-z0-9_]*$'),
  tipe text NOT NULL CHECK (tipe IN ('string', 'integer', 'boolean', 'date', 'enum')),
  wajib boolean NOT NULL,
  nilai_diizinkan jsonb,
  aturan_validasi jsonb,
  klasifikasi text NOT NULL CHECK (klasifikasi IN ('Internal', 'Terbatas', 'Rahasia')),
  kirim_ke_data_balikan boolean NOT NULL,
  deskripsi text NOT NULL CHECK (length(deskripsi) > 0),
  versi integer NOT NULL CHECK (versi >= 1),
  PRIMARY KEY (downstream_endpoint_id, nama_field),
  CONSTRAINT enum_butuh_nilai CHECK (tipe <> 'enum' OR nilai_diizinkan IS NOT NULL)
);

-- ---------------------------------------------------------------- client credentials and access (EN-02, EN-03)
CREATE TABLE client_kredensial (
  credential_id uuid PRIMARY KEY,
  client_id uuid NOT NULL REFERENCES client (client_id),
  jenis text NOT NULL CHECK (jenis IN ('oauth2_client_credentials', 'api_key')),
  kunci_hash bytea NOT NULL,                           -- hash of client secret / API key, write-only
  -- EN-03: physical names chosen here (contract 3.2.6 leaves naming to the schema design)
  status text NOT NULL DEFAULT 'aktif' CHECK (status IN ('aktif', 'dicabut')),
  dicabut_at timestamptz,
  dicabut_oleh uuid REFERENCES admin_user (pengguna_id),
  kedaluwarsa_at timestamptz,                          -- authentication only, not K-20 (EN-02)
  dibuat_at timestamptz NOT NULL DEFAULT now(),
  dibuat_oleh uuid NOT NULL REFERENCES admin_user (pengguna_id),
  CONSTRAINT dicabut_lengkap CHECK (
    (status = 'dicabut') = (dicabut_at IS NOT NULL) AND (status = 'dicabut') = (dicabut_oleh IS NOT NULL)
  )
);
CREATE INDEX client_kredensial_client_idx ON client_kredensial (client_id);

-- EN-03: revoked is terminal, for every write path (not only the function), and max 2 active per client (ADR-0001 5a.5).
CREATE FUNCTION tg_kredensial_terminal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.status = 'dicabut' AND (NEW.status <> 'dicabut' OR NEW.dicabut_at IS DISTINCT FROM OLD.dicabut_at
                                   OR NEW.dicabut_oleh IS DISTINCT FROM OLD.dicabut_oleh) THEN
      RAISE EXCEPTION 'kredensial_dicabut_terminal' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.credential_id <> OLD.credential_id OR NEW.client_id <> OLD.client_id THEN
      RAISE EXCEPTION 'credential_id dan client_id tidak boleh diubah' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.status = 'aktif' AND (TG_OP = 'INSERT' OR OLD.status <> 'aktif') THEN
    PERFORM 1 FROM client WHERE client_id = NEW.client_id FOR UPDATE;
    IF (SELECT count(*) FROM client_kredensial
         WHERE client_id = NEW.client_id AND status = 'aktif' AND credential_id <> NEW.credential_id) >= 2 THEN
      RAISE EXCEPTION 'maksimal 2 kredensial aktif per client' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER client_kredensial_terminal BEFORE INSERT OR UPDATE ON client_kredensial
  FOR EACH ROW EXECUTE FUNCTION tg_kredensial_terminal();

CREATE TABLE client_endpoint (
  client_id uuid NOT NULL REFERENCES client (client_id),
  downstream_endpoint_id uuid NOT NULL REFERENCES downstream_endpoint (downstream_endpoint_id),
  PRIMARY KEY (client_id, downstream_endpoint_id)
);

-- ---------------------------------------------------------------- webhook configuration (contract 3.7)
CREATE TABLE client_webhook (
  client_id uuid PRIMARY KEY REFERENCES client (client_id),
  webhook_url varchar(2048) NOT NULL CHECK (webhook_url ~ '^https://'),
  aktif boolean NOT NULL,
  secret_versi integer NOT NULL CHECK (secret_versi >= 1),
  secret_ciphertext bytea NOT NULL,
  secret_dek_terbungkus bytea NOT NULL,
  secret_nonce bytea NOT NULL,
  kek_id varchar(100) NOT NULL,
  diubah_at timestamptz NOT NULL DEFAULT now(),
  diubah_oleh uuid NOT NULL REFERENCES admin_user (pengguna_id)
);

CREATE TABLE webhook_domain_allowlist (
  domain varchar(253) PRIMARY KEY CHECK (domain = lower(domain)),
  aktif boolean NOT NULL DEFAULT true,
  diubah_at timestamptz NOT NULL DEFAULT now(),
  diubah_oleh uuid NOT NULL REFERENCES admin_user (pengguna_id)
);

-- ---------------------------------------------------------------- platform settings, config audit
CREATE TABLE konfigurasi_platform (
  kunci text PRIMARY KEY,
  nilai jsonb NOT NULL,
  diubah_at timestamptz NOT NULL DEFAULT now(),
  diubah_oleh uuid REFERENCES admin_user (pengguna_id)
);
INSERT INTO konfigurasi_platform (kunci, nilai) VALUES ('ekspor_batas_baris', '10000'::jsonb),
  ('rekonsiliasi_ambang_detik', '60'::jsonb);   -- contract E-03

-- ADR-0001 section 7 / EN-07 / EN-08: who, when, entity, old -> new, reason. terjadi_at is the transaction time,
-- so every row written by one mass-cancel transaction shares it.
CREATE TABLE audit_konfigurasi (
  audit_konfigurasi_id uuid PRIMARY KEY,
  terjadi_at timestamptz NOT NULL DEFAULT now(),
  pengguna_id uuid NOT NULL REFERENCES admin_user (pengguna_id),
  entitas_jenis text NOT NULL CHECK (entitas_jenis IN (
    'client', 'kredensial', 'downstream_endpoint', 'downstream_pool', 'upstream_pool', 'provider',
    'client_webhook', 'webhook_domain_allowlist', 'provider_config', 'endpoint_config',
    'endpoint_metadata_field', 'konfigurasi_platform', 'admin_user')),
  entitas_id uuid,
  aksi text NOT NULL CHECK (aksi IN ('buat', 'ubah', 'nonaktifkan', 'aktifkan', 'cabut', 'ditolak')),
  nilai_lama jsonb,
  nilai_baru jsonb,                                    -- never secret values
  alasan text NOT NULL CHECK (length(btrim(alasan)) > 0),
  jumlah_cancelled integer CHECK (jumlah_cancelled >= 0),   -- EN-08
  jumlah_failed integer CHECK (jumlah_failed >= 0),
  CONSTRAINT jumlah_aksi_k20 CHECK ((jumlah_cancelled IS NULL) = (jumlah_failed IS NULL))
);
CREATE INDEX audit_konfigurasi_entitas_idx ON audit_konfigurasi (entitas_jenis, entitas_id, terjadi_at);
CREATE INDEX audit_konfigurasi_terjadi_idx ON audit_konfigurasi (terjadi_at);

-- ---------------------------------------------------------------- immutability helpers
-- V-03: a configuration version is never changed or deleted.
CREATE FUNCTION tg_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% bersifat tidak dapat diubah (V-03)', TG_TABLE_NAME USING ERRCODE = 'integrity_constraint_violation';
END $$;
CREATE TRIGGER provider_config_versi_immutable BEFORE UPDATE OR DELETE ON provider_config_versi
  FOR EACH ROW EXECUTE FUNCTION tg_immutable();
CREATE TRIGGER endpoint_config_versi_immutable BEFORE UPDATE OR DELETE ON endpoint_config_versi
  FOR EACH ROW EXECUTE FUNCTION tg_immutable();

-- Append-only tables: only the future archive job role may delete (contract DQ-21, section 8.3).
CREATE FUNCTION tg_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_user = 'pr_job_arsip' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION '% bersifat append-only', TG_TABLE_NAME USING ERRCODE = 'integrity_constraint_violation';
END $$;
CREATE TRIGGER audit_konfigurasi_append_only BEFORE UPDATE OR DELETE ON audit_konfigurasi
  FOR EACH ROW EXECUTE FUNCTION tg_append_only();
CREATE TRIGGER audit_konfigurasi_no_truncate BEFORE TRUNCATE ON audit_konfigurasi
  FOR EACH STATEMENT EXECUTE FUNCTION tg_append_only();
